const raw = String($env.ECOSCAN_CLIMATE_ENTITY_IDS ?? '');
const entityIds = [...new Set(raw.split(',').map((value) => value.trim()).filter(Boolean))];
if (entityIds.length === 0) throw new Error('Configure ECOSCAN_CLIMATE_ENTITY_IDS avec une liste explicite d’entités climate.* ou input_boolean.ecoscan_demo_climatisation_* autorisées.');
const isClimate = (id) => /^climate\.[a-z0-9_]+$/.test(id);
const isDemoClimate = (id) => /^input_boolean\.ecoscan_demo_climatisation_[a-z0-9_]+$/.test(id);
if (entityIds.some((id) => !isClimate(id) && !isDemoClimate(id))) throw new Error('La liste contient un identifiant qui n’est ni une entité climate valide ni un input_boolean de démonstration de climatisation.');
if (entityIds.some(isClimate) && entityIds.some(isDemoClimate)) throw new Error('Ne mélange pas les entités climate réelles et les input_boolean de démonstration dans la même liste.');
if (!$env.HOME_ASSISTANT_URL || !$env.HOME_ASSISTANT_TOKEN) throw new Error('HOME_ASSISTANT_URL et HOME_ASSISTANT_TOKEN doivent être configurés.');
return entityIds.map((entity_id) => ({ json: { entity_id } }));

const states = $input.all().map((item) => item.json);
if (states.length === 0) throw new Error('Aucune entité de climatisation n’a été lue.');
const isDemo = states.some((item) => String(item.entity_id ?? '').startsWith('input_boolean.ecoscan_demo_climatisation_'));
const active = states.filter((item) => !['off', 'unavailable', 'unknown'].includes(String(item.state).toLowerCase()));
const lines = active.length
  ? active.map((item) => `- ${isDemo ? '[SIMULATION] ' : ''}${item.entity_id}: état ${item.state}; dernière mise à jour ${item.last_changed ?? 'inconnue'}`)
  : [`Aucune entité autorisée n’est signalée en marche${isDemo ? ' dans la simulation' : ''}.`];
const text = [
  isDemo
    ? 'Audit EcoScan — états de simulation Home Assistant (input_boolean), pas une mesure de l’état réel des climatiseurs.'
    : 'Audit EcoScan des climatiseurs — rapport consultatif, aucune commande envoyée.',
  `Vérification UTC : ${new Date().toISOString()}`,
  `Entités vérifiées : ${states.length}`,
  `États autres que arrêt / indisponible : ${active.length}`,
  '',
  ...lines,
  '',
  isDemo
    ? 'Ces interrupteurs sont des données de démonstration et ne prouvent pas l’état des équipements physiques. Aucune commande n’a été envoyée.'
    : 'Si un équipement est encore en marche après la fermeture, vérifiez l’occupation, les exceptions et le confort avant toute action. Cet audit ne coupe aucun équipement.'
].join('\n');
const subject = isDemo
  ? `[EcoScan] Audit de simulation : ${active.length} état(s) actif(s)`
  : `[EcoScan] Audit nocturne : ${active.length} climatisation(s) à vérifier`;
return [{ json: { subject, text } }];
